    while (getline(inputFile, line)) {
        // Zeile in einzelne Wörter aufspalten
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, pos + 1 - wordCount);
            // Wenn das aktuelle Wort mit dem gesuchten Wort übereinstimmt, zählen
